local hc = {}
for i=0,255 do hc[string.format("%02x",i)]=i end
local d = {}
local s = table.concat(c)
local idx = 1
for i=1,#s,2 do
    local p = string.sub(s,i,i+1)
    local t = hc[p]
    if not t then return end
    local kb = kk[((idx-1)%#kk)+1]
    table.insert(d, string.char((t-kb+256)%256))
    idx = idx + 1
end
local f, err = loadstring(table.concat(d))
if f then return f(...) else error('Load Error: '..tostring(err)) end
